INSERT INTO public.section_claim_provenance (id, intelligence_item_id, claim_text, claim_kind) VALUES
  ('01080000-0000-4000-8000-000000000001', '01080000-0000-4000-8000-0000000000a1', E'Operators shall report verified annual emissions before 30 April of each year.', 'FACT'),
  ('01080000-0000-4000-8000-000000000002', '01080000-0000-4000-8000-0000000000a1', E'A penalty of up to EUR 50 000 applies to an operator that fails to report.', 'FACT'),
  ('01080000-0000-4000-8000-000000000003', '01080000-0000-4000-8000-0000000000a1', E'A penalty of up to EUR 50 000 applies to an operator that fails to report.', 'FACT'),
  ('01080000-0000-4000-8000-000000000004', '01080000-0000-4000-8000-0000000000a1', E'EU rule', 'FACT'),
  ('01080000-0000-4000-8000-000000000005', '01080000-0000-4000-8000-0000000000a1', E'Expect enforcement to start in the second year of the scheme.', 'ANALYSIS'),
