INSERT INTO public.intelligence_item_sections (id, item_id, section_key, section_order, content_md, is_conditional) VALUES ('01080000-0000-4000-8000-0000000000b1', '01080000-0000-4000-8000-0000000000a1', '1', 1, E'**SCOPE** Operators shall report verified annual emissions before 30 April of each year. Source: EUR-Lex, Regulation, 2026 https://eur-lex.europa.eu/x\n\n**PENALTY** A penalty of up to EUR 50 000 applies to an operator that fails to report. Source: EUR-Lex, Regulation, 2026 https://eur-lex.europa.eu/x\n  \nA paragraph of plain prose that no claim states.\n\n\nThe EU rule applies to ships calling at Union ports.\n\n<!-- claim:01080000-0000-4000-8000-000000000001 -->\nA penalty of up to EUR 50 000 applies to an operator that fails to report. Source: x https://x.test/a\n \nOperators shall report verified annual emissions before 30 April of each year. The scheme enters into force on 1 January 2027 for all operators.\n\n[effective_date] The scheme enters into force on 1 January 2027 for all operators.\n\nAnalytical inference: Expect enforcement to start in the second year of the scheme.\n\nTHE SCHEME ENTERS INTO FORCE ON 1 JANUARY 2027 FOR ALL OPERATORS. Source: x https://x.test/b', false);
